def _read_launch_report(report: Path) -> str:
    try:
        with os.fdopen(_open_report(report, os.O_RDONLY), "rb") as source:
            raw = source.read(MAX_REPORT_BYTES)
    except OSError:
        return ""
    text = raw.decode("utf-8", "replace")
    return _bounded(text).strip()


